export const graduateNames: string[] = ["الخريجة حُسن علي العولقي 👩‍🎓","الخريج 2","الخريج 3","الخريج 4"];
export const graduateMessages: GraduateMessage[] = [{"name":"الخريجة حُسن علي العولقي 👩‍🎓","messageHtml":"\n      <h2>رسالة خريجة – دفعة 2025 🎓</h2>\n      <p>أنا حُسن علي العولقي، خريجة بكالوريوس محاسبة من جامعة العلوم والتكنولوجيا،</p>\n      <p>أكتب هذه الكلمات والامتنان يملأ قلبي، والفخر يرسم ملامح هذه اللحظة التي انتظرتها طويلًا.</p>\n      <p>سنوات مضت بين دفاتر الأرقام، ومعادلات التحليل، وساعات الدراسة والسهر،</p>\n      <p>كانت رحلةً مليئة بالتحديات والاختبارات، لكنها كانت أيضًا مليئة بالنضج، والاكتشاف، والتعلّم العميق.</p>\n      <p>تعلمت أن النجاح لا يُهدى، بل يُصنع خطوة بخطوة، في كل فجرٍ استيقظت فيه على تعبٍ لم يذهب سدى،</p>\n      <p>وفي كل لحظة شكٍّ واجهتها بالإيمان بأن الله لا يضيع تعب من اجتهد وسعى.</p>\n      <strong>إلى كل من يسير في الطريق الذي كنتُ فيه يومًا:</strong>\n      <ul>\n        <li>💫 لا تستعجلوا الوصول، فكل تأخير يحمل في طيّاته درسًا، وكل صعوبة تترك فيكم أثرًا سيصنع منكم يومًا شخصًا أقوى.</li>\n        <li>💫 ثقوا بأن العثرة ليست نهاية، بل دليل على أنكم تتحركون نحو هدفٍ حقيقي.</li>\n        <li>💫 استعينوا بالله في كل خطوة، فهو وحده من يبدل الخوف طمأنينة، والتعب فرحًا.</li>\n      </ul>\n      <strong>ولزملائي الذين سيحملون الراية من بعدنا:</strong>\n      <p>تعلموا أن العلم ليس درجاتٍ وشهادات، بل بصمة نتركها في الحياة،</p>\n      <p>وأن التفوق لا يقاس بالعلامات، بل بما تضيفونه من أثر في قلوب الناس وفي مجالات عملكم.</p>\n      <p>ابنوا لأنفسكم حلمًا يستحق أن يُروى، ولا تجعلوا المقارنة تسرق منكم متعة السعي.</p>\n      <p>اليوم، وأنا أنتهى من مناقشة بحثي لا أراها مجرد أوراق، بل أراها خلاصة سنوات من الإصرار، وبداية رحلةٍ جديدة من العطاء والمهنية.</p>\n      <p>فالنجاح ليس نهاية الطريق، بل بدايته الحقيقية.</p>\n      <blockquote>“ومن يتوكل على الله فهو حسبه…”</blockquote>\n      <p>بهذه الثقة بدأت رحلتي، وبهذا الإيمان أواصل طريقي.</p>\n      <p><strong>دفعة 2025 ✨</strong><br>دفعة الأحلام الكبيرة… والعزيمة التي لا تنكسر.<br>فخر اليوم… وأمل الغد.</p>"},{"name":"الخريج 2","messageHtml":""},{"name":"الخريج 3","messageHtml":""},{"name":"الخريج 4","messageHtml":""}];
export const graduateResearch: GraduateResearch[] = [{"name":"الخريجة حُسن علي العولقي 👩‍🎓","files":[{"text":"📘 دور المحاسبة الإدارية في تحسين الأداء المالي","url":"https://drive.google.com/file/d/1kPotyMQOQQKU8qLlOm9xrwd4c0cbfGom/view?usp=drivesdk"},{"text":"📗 عرض تقديمي للبحث","url":"https://docs.google.com/presentation/d/1Y2pZUDzAEmyzDcYXvX1Fdaw2SbrHF0kv/edit?usp=drivesdk"},{"text":"📙 الخطة المقترحة دور المحاسبة الإدارية في تحسين الأداء المالي","url":"https://drive.google.com/file/d/1Rp3DzTGXf75XLTgJDpTw-1-v7YH1ooZq/view?usp=drivesdk"}]},{"name":"الخريج 2","files":[]},{"name":"الخريج 3","files":[]},{"name":"الخريج 4","files":[]}];

export const welcomeMessages: WelcomeMessage[] = [{"id":"msg1","name":"محمد منير","content":"<p>السلام عليكم</p>\r\n\r\n<p>إلى كل من اختار طريق العلم، وسار فيه بخطى ثابتة رغم الصعوبات،</p>\r\n<p>إلى من يسهر الليالي بين الكتب والمذكرات، يؤمن أن المستقبل لا يُعطى، بل يُصنع…</p>\r\n\r\n<p>العلم ليس مجرد كلمات تُحفظ أو كتب تُقرأ، بل هو نورٌ في القلب، وعزٌّ في الدنيا، ورفعةٌ في الآخرة.</p>\r\n<p>به تُبنى الأمم، وتُعمر الأرض، وتُصان الكرامة، فالأمم التي تزرع في أبنائها حبّ التعلم، تحصد التقدم والريادة.</p>\r\n\r\n<blockquote>\r\nقال الله تعالى:<br>\r\n{ ‏‏يَرْفَعِ اللَّهُ الَّذِينَ آمَنُوا مِنكُمْ وَالَّذِينَ أُوتُوا الْعِلْمَ دَرَجَاتٍ }\r\n</blockquote>\r\n\r\n<blockquote>\r\nوفي الحديث الشريف:<br>\r\n\"منْ سَلَكَ طَريقًا يَبْتَغِي فِيهِ علْمًا سهَّل اللَّه لَه طَريقًا إِلَى الجنةِ.\"\r\n</blockquote>\r\n\r\n<p>فالعلم طريق الأنبياء والعظماء، وبه ترتقي العقول وتزدهر الأوطان.</p>\r\n<p>وما أجمل أن يكون لك هدف نبيل تسعى إليه، أن تتعلم لتفيد، وتعمل لتُحدث فرقاً.</p>\r\n<p>قد يكون الطريق طويلاً ومتعباً، لكن كل تعب اليوم هو راحة الغد، وكل جهد تبذله اليوم هو استثمار في نفسك ومستقبلك.</p>\r\n\r\n<p><strong>تذكّر دائماً:</strong></p>\r\n<p>كل ساعة تقضيها في طلب العلم هي لبنة تبني بها مجدك،</p>\r\n<p>وكل صبر تبذله اليوم سيُثمر نجاحاً يليق بعزيمتك غداً.</p>\r\n\r\n<p>فاجعل من العلم رسالتك، ومن المثابرة طريقك،</p>\r\n<p>واعمل بصمت، ودع إنجازك يتحدث عنك. 🌟</p>"},{"id":"msg2","name":"سالم","content":"<p>في عالمٍ يُقاس فيه النجاح بسهولة الطريق لا بعمق التجربة، وُلدت لأتعلم أن الصبر ليس ضعفًا، بل فنّ البقاء واقفًا وسط العواصف.</p>\r\n<p>لم تكن بدايتي ممهّدة بالفرص، ولم تُفرش دروبي بالورود، بل كانت مليئةً بالحجارة التي صنعت منها سُلّمًا نحو نفسي.</p>\r\n<p>عرفت منذ وقتٍ مبكر أن الحياة لا تمنحك ما تريد، بل تختبرك لتعرف كم أنت مستعد لأن تنهض بعد كل سقوط.</p>\r\n\r\n<p>لطالما كان الحلم يرافقني، يهمس لي في الليالي الطويلة أن لا أتوقف.</p>\r\n<p>حلمت أن أكمل دراستي الجامعية خارج البلاد، أن أغادر حدود المألوف لأصل إلى عالمٍ أوسع من المعرفة والتجربة، لكن القدر كان له مسار آخر.</p>\r\n<p>شعرت بخيبةٍ حين لم أستطع تحقيق ذلك، غير أن الحلم لم يمت في قلبي، بل تحوّل إلى طاقة، إلى نارٍ هادئة تدفعني لأكمل بثلاثة تخصصات في وقتٍ واحد، أبحث من خلالها عن نفسي قبل أن أبحث عن لقبٍ أكاديمي.</p>\r\n<p>كنت أتعلم لأفهم، لا لأتفاخر. كنت أبحث عن المعنى، لا عن المظهر.</p>\r\n\r\n<p>ثم جاءت مرحلة أصعب، حين اضطررت لمغادرة وطني إلى بلادٍ جديدة، لا تشبه وجهي ولا لهجتي، لكنني احتضنتها بحبّ، وواصلت فيها ما تبقّى من دراستي.</p>\r\n<p>هناك، بين الغربة والحنين، تعلمت أن القوة ليست فيما نملك، بل فيما نستطيع تجاوزه.</p>\r\n<p>كل يوم كان اختبارًا جديدًا للإرادة، وكل لحظة تعب كانت درسًا في الصبر، وكل تحدٍّ كان يقول لي: \"ما زلتَ قادرًا على النهوض.\"</p>\r\n\r\n<p>وكان الله هو السند والنور في كل خطوةٍ مظلمة.</p>\r\n<p>حين تخلّى عني البعض، لم يتركني الله.</p>\r\n<p>إيماني به كان الحبل الذي أنقذني من الغرق، وثقتي بمشيئته كانت البوصلة التي أعادتني إلى الطريق حين ضعت.</p>\r\n<p>لم أفقد الأمل يومًا، لأنني أدركت أن كل تأخير يحمل في طيّاته خيرًا، وأن كل خسارة تُنبت بداخلك شيئًا جديدًا، لو أنك فقط صبرت.</p>\r\n\r\n<p>خسرت كثيرًا: فرصًا، أشخاصًا، لحظاتٍ ظننتها ستصنع فرقًا في حياتي. لكنني لم أخسر نفسي.</p>\r\n<p>بقيت تلك الشعلة الصغيرة بداخلي، تُذكّرني أن الطريق الطويل لا يُخيف من عرف سبب سيره.</p>\r\n<p>لم أسمح لليأس أن يحكم عليّ، ولا للفشل أن يُعرّفني.</p>\r\n<p>تعلمت أن الإنسان لا يُقاس بما يملك، بل بما يستطيع تجاوزه، وأن العظمة ليست في الوصول، بل في الإصرار على المحاولة.</p>\r\n\r\n<p>كانت الدراسة بالنسبة لي أكثر من مجرد كتبٍ وأوراق. كانت معركة مع ذاتي، مع الخوف، مع التعب.</p>\r\n<p>كم مرة شعرت أن كل شيء انهار؟ كثيرة، لكني كنت أعود في كل مرة، أجمع نفسي، أتنفس، وأبدأ من جديد.</p>\r\n<p>كنت أتعلم لأنني أؤمن أن العلم طريقٌ للكرامة، وأن من يملك المعرفة يملك حريته.</p>\r\n<p>كل ليلةٍ سهرت فيها كانت بذرة نجاح، وكل صباحٍ استيقظت فيه رغم التعب كان انتصارًا صغيرًا على المستحيل.</p>\r\n\r\n<p>واليوم، حين أنظر إلى الطريق خلفي، لا أرى الخيبات، بل أرى الدروس.</p>\r\n<p>لا أرى السقوط، بل أرى النهوض.</p>\r\n<p>لقد علّمتني الحياة أن الإرادة لا تُقهر، وأن المثابرة تصنع المعجزات، وأن من يمضي رغم الألم هو المنتصر الحقيقي.</p>\r\n\r\n<p><strong>رسالتي لكل من يقرأ هذه الكلمات:</strong></p>\r\n<p>لا تدع الظروف تُقنعك بأنك ضعيف.</p>\r\n<p>لا تسمح لليأس أن يسرق منك حلمك.</p>\r\n<p>كل تعبٍ ستعيشه اليوم سيُثمر غدًا، وكل فشلٍ سيقودك إلى طريقٍ أنضج.</p>\r\n<p>واصل، وتعلّم، واعمل، حتى وإن لم يصفّق لك أحد.</p>\r\n<p>فالحياة تُنصِف في النهاية من صدق مع نفسه، ومن جعل من ألمه معنى.</p>\r\n\r\n<p>اصنع من رحلتك رسالة، ومن تعبك شهادة على أنك قاومت ولم تنكسر.</p>\r\n<p>فالحلم لا يموت إلا حين تتخلى عنه أنت.</p>\r\n<p>واصل الطريق، فكل خطوةٍ مهما بدت صغيرة، هي فصل جديد في قصة عظيمة اسمها <strong>أنت</strong>.</p>"},{"id":"msg3","name":"إيلاف","content":"<p>إلى من اختاروا طريق العلم، وإن بعدت المسافات،</p>\r\n<p>إلى من يدرسون في صمت، خلف الشاشات، ويصنعون الفرق بصبرهم وعزيمتهم…</p>\r\n\r\n<p>الدراسة عن بُعد ليست طريقًا سهلًا، لكنها طريق <em>يعلّمك المعنى الحقيقي للصبر، والانضباط، والاجتهاد في الخفاء.</em></p>\r\n<p>أن تدرس دون معلم أمامك، دون أصدقاء يحيطون بك، وتتحدى الانشغال والملل والوحدة… <em>هذا بحد ذاته إنجازٌ عظيم.</em></p>\r\n\r\n<p><em>ولا تنسَ… أن العودة بعد الانقطاع قوة.</em></p>\r\n<p>أن تنهض من جديد بعد أن ظننت أن الدراسة لم تعد لك، أن تجد في نفسك القدرة على إكمال طريق ظننته قد انتهى…</p>\r\n<p>هذا نصر عظيم يستحق أن تفخر به.</p>\r\n<p><em>فطول الانتظار لا يعني الفشل، بل يعني أن الوقت الذي كتبه الله لك قد اقترب.</em></p>\r\n\r\n<p>كم من مرة شعرت فيها أن حلمك بعيد؟</p>\r\n<p>وها أنت اليوم تقترب منه، خطوة بخطوة، <em>برحمة الله أولاً، ثم بصبرك وجهدك وتوكل قلبك.</em></p>\r\n\r\n<p><em>لا تظن أن الله لا يرى تعبك.</em></p>\r\n<p>كل لحظة تقضيها في مذاكرة، كل اختبار تحضّر له في منتصف الليل، كل مرة قاومت فيها التسويف…</p>\r\n<p>هي خطوات تُكتب لك، وتُقربك من تحقيق حلمك، ومن رضا الله عز وجل.</p>\r\n\r\n<p>الدراسة عن بعد تُعلّمك كيف <em>تحب العلم لذاته، لا لزخرف شكله.</em></p>\r\n<p>تجعلك تشتاق للمعرفة، وتغرس فيك شغفًا هادئًا، صامتًا… لكنه راسخ.</p>\r\n\r\n<blockquote>\r\nقال تعالى:<br>\r\n<em>\"واصبر وما صبرك إلا بالله…\"</em>\r\n</blockquote>\r\n\r\n<p>أنتم من يصنع المعجزات بصبر لا ينكسر، وإرادة لا تعرف المستحيل. رغم البُعد والمسافات، يظل شغفكم نبراسًا يضيء طريقكم نحو مستقبل مشرق.</p>\r\n\r\n<p>ليس سهلاً أن تواصلوا رحلة العلم بلا مقاعد تقليدية، لكنكم اخترتم طريق الإصرار والتحدي، تثبتون أن الحلم لا يموت مهما طال الانتظار.</p>\r\n\r\n<p>تذكروا دومًا أن كل دقيقة تقضونها في الدراسة هي استثمار في ذاتكم، وكل تحدي تواجهونه هو خطوة تقربكم من النجاح الذي تستحقونه.</p>\r\n\r\n<p>أنتم ليسوا فقط طلابًا، بل رواد تصنعون قصة فريدة من الصبر، العزيمة، والتفاني. استمروا، فالنجاح قادم، وأنتم تستحقونه بجدارة.</p>"},{"id":"msg4","name":"إيمان","content":"<p>قبل دخولي الجامعة، كنتُ أحمل في داخلي حلماً كبيراً بأن أصبح دكتورة، أرى في ذلك شفاءً لما عشته من معاناةٍ وصعوباتٍ في بداياتي، وكأن في الحلم خلاصًا من كل ما مررت به من وجع.</p>\r\n<p>لكن الأقدار أخذت بيدي إلى تخصص المحاسبة، ذلك التخصص الذي لم يكن في الحسبان، لكنه مع مرور الأيام أصبح مرآةً لرحلتي، ودفترًا كتبتُ فيه فصول صبري وإصراري.</p>\r\n\r\n<p>لم تكن الرحلة سهلة… كانت مليئةً بالمواقف التي كسرتني لتبني بداخلي صلابةً لا تهتز، وبالأيام التي شعرتُ فيها بالوحدة وأنا أقاوم لأثبت لنفسي أنني قادرة، مهما كان الطريق طويلاً.</p>\r\n<p>كنتُ أبتسم رغم التعب، أُخفي الدموع وأمضي، لأنني كنت أؤمن أن ما بعد العسر إلا الفرج، وأن كل وجعٍ اليوم هو تمهيدٌ لمجدٍ غدًا.</p>\r\n\r\n<p>ولأجل أن أُكمل طريقي، كنتُ أرحل إلى الرياض في فترات الاختبارات، أتحمّل مشقة السفر والبعد عن أهلي، أحمل معي كتبي وأوراقي وكأنني أحمل العالم بين يديّ.</p>\r\n<p>في كل رحلة ذهابٍ وعودة، كنت أراجع، أقيّم، وأستدرك ما فاتني، أحمل تلك الأوراق بين يديّ كما لو كنت أحمل مستقبلي، لا تهمّني درجةٌ سيئة أو جميلة، فالعبرة لم تكن في الأرقام بل في الحصيلة التي خرجت بها من كل تجربة.</p>\r\n\r\n<p>كم من ليلةٍ جلستُ فيها أذاكر ودموعي تسبق الكلمات، أراجع وأشرح لنفسي كأنني أواسيها، أتابع الشروحات وقلبي يهمس لي: “ستمضين، فقط تابعي.”</p>\r\n<p>وكنتُ كل مرة أدخل قاعة الاختبار بقلبٍ مملوءٍ بالأمل، أؤمن أن الله لن يضيع جهدي، وأن التعب لا يذهب سُدى.</p>\r\n\r\n<p>وكم هو شعورٌ غامر حين أنهي مادةً بعد رحلةٍ طويلة من السهر، فأسلّم ورقتي وكأنني أودّع فصلًا من حياتي، لحظاتٌ قصيرة تختزل سنواتٍ من الكفاح، لكنها تملؤني بسعادةٍ لا توصف، لأنني أرى ثمار جهدي تزهر أمامي.</p>\r\n\r\n<p>رحلتي مع المحاسبة لم تكن مجرد دراسة، بل كانت مدرسةً للحياة، تعلّمتُ فيها أن الحساب لا يكون بالأرقام فقط، بل بالمواقف والدروس والعِبر.</p>\r\n<p>فالمحاسبة هي فنّ الحسابات بالقيود والجداول المسطّرة، فإن أتقنتها، أتقنتَ حسابات الحياة.</p>\r\n\r\n<p>واليوم، وأنا على أعتاب التخرّج، أسترجع كل ما مررت به بين بدايتي ونهايتي، وأشعر بالفخر والذهول معًا.</p>\r\n<p>لا أكاد أصدق أنني وصلت، وأن كل تلك الليالي الطويلة والدموع والدعوات كانت طريقًا ممهّدًا لهذه اللحظة العظيمة.</p>\r\n<p>وفي النهاية، أعود إلى أمي وكلي فخر وسعادة لأقول:<br><strong>\"أماه، فعلتُها.. فلتفخري بابنتك، فقد أوفت بالعهد ووصلت.\"</strong></p>\r\n\r\n<p><strong>رسالتي لطلاب المحاسبة القادمين:</strong></p>\r\n<p>اعلموا أن طريقكم قد يبدو معقدًا كما الجداول التي تملؤونها، لكنه مليء بالمعاني لمن يفهمه.</p>\r\n<p>لا تخافوا من الصعاب، فكل رقمٍ خاطئ يمكن تصحيحه، وكل محاولةٍ تقرّبكم من الإتقان.</p>\r\n<p>لا تظنوا أن الحياة تتوقف عند درجةٍ أو مادة، فالوقت لا يقف، والدنيا لا تنتهي عند مرحلة.</p>\r\n<p>واصلوا السعي بإيمانٍ ومثابرة، فـ النهاية دائمًا أجمل لمن لم يتوقف في المنتصف.</p>"},{"id":"msg5","name":"صادق جزيلان","content":"<p>الحمد للهِ الذي رفعَ بالعلمِ شأنَ أهله، وفضَّلَهم على غيرهم درجات، والصلاةُ والسلامُ على سيّدنا محمدٍ، خيرِ من علّم وأرشد، وعلى آله وصحبه ومن اقتفى أثرهم إلى يوم الدين.</p>\r\n\r\n<p>وبعدُ، فليكن سعيُكم في طلبِ العلم سعيًا مباركًا، تُخلّد به أسماؤكم، وتُروى به قصصُ عزائمكم في صفحاتِ المجد والعطاء.</p>\r\n<p>اجعلوا من أعماركم جسورًا للخير، ومن علمكم مصابيحَ تضيءُ دروبَ الآخرين.</p>\r\n<p>فالكلمةُ الصادقةُ والعملُ المخلصُ لا يضيعان عند الله، بل يبقيان نورًا بعد الرحيل، وذكرًا طيبًا في القلوب.</p>\r\n\r\n<p>ولعلّ هذه الأبيات التي نظمتها تعبّر عمّا في نفسي من محبةٍ لكم، ودعاءٍ بأن يجعل الله علمكم نافعًا، وجهودكم مباركة:</p>\r\n\r\n<blockquote>\r\nسأبذلُ ما بوسعي يا رفاقي<br>\r\nبإخلاصٍ إلى الرحمنِ راقي<br>\r\nولا يبقى من الدنيا بقاءٌ<br>\r\nسوى علمٍ وراءَ الموتِ باقي<br>\r\nفيا كلَّ الذين رأوا جهودي<br>\r\nأريدُ دعاءَكم للقبرِ ساقي<br>\r\nألا باللهِ لا تنسَوا أخاكم<br>\r\nإذا حانَتْ بنا ساعُ الفِراقِ<br>\r\nوكم من دعوةٍ نجّتْ أخاها<br>\r\nوكان بها النجاةُ من احتراقِ\r\n</blockquote>"},{"id":"msg6","name":"عبدالمجيد","content":"<p>من ضيق الحياة إلى رحاب العلم</p>\r\n\r\n<p>أنا عبدالمجيد، طالبٌ لم يكن طريقه مفروشًا بالورود، بل كان مليئًا بالحجارة، بعضها وضعها القدر، وبعضها حملتها الأوطان المثقلة بالأزمات.</p>\r\n\r\n<p>درست في اليمن، ثم انتقلت إلى السعودية، وهناك أكملت الثانوية وسط ظروفٍ لم تكن سهلة، فأنا أجنبي لا أملك سوى تأشيرة زيارة، ومع ذلك لم أتنازل عن حلمي.</p>\r\n\r\n<p>قررت أن أهاجر إلى بلدٍ أقل كلفة، فكانت السودان خياري الوحيد، وهناك بدأت رحلتي نحو الهندسة، ذلك الحلم الذي سكنني منذ الصغر.</p>\r\n\r\n<p>دفعتني الظروف إلى أن أطلب من أهلي تقليص مصاريف المنزل، لأجل أن أواصل تعليمي، ولبّوا النداء رغم ضيق الحال، فكانوا سندي في زمنٍ عزّ فيه السند.</p>\r\n\r\n<p>درست، وواجهت رسومًا مرتفعة، ثم جاءت المظاهرات، وتعثرت السودان كما تعثرت اليمن، فعدت إلى بلدي، أبحث عن بصيص أملٍ لإكمال الدراسة، لكن الأبواب أُغلقت.</p>\r\n\r\n<p>تسلل اليأس إلى قلبي، فقررت أن أعمل، أن أهاجر، أن أؤجل حلمي، لكن الحلم لم يؤجلني.</p>\r\n\r\n<p>مرت السنوات، سنة وسنتان وثلاث، حتى بلغت خمسًا، قررت أن أعيش بلا شهادة، لكن شيئًا في داخلي ظلّ يصرخ: \"أكمل، لا تتوقف، لا تدفن نفسك حيًّا.\"</p>\r\n\r\n<p>قررت أن أعمل وأبني مستقبل أولادي، ألا أتركهم فريسةً للجهل كما كنت، لكنني ما زلت أبحث عن عملٍ يليق بقدراتي، وما زالت الشهادة حاجزًا بيني وبين القبول.</p>\r\n\r\n<p>ثم جاءني دافعٌ من الله، دافعٌ لا يُقاوَم، دافعٌ للتعلّم، للتحدي، للعودة من جديد.</p>\r\n\r\n<p>بحثت، وسألت، وتشعبت، حتى وصلت إلى هذه الجامعة، هذا الصرح، وسجلت فيه، وها أنا ذا في بداية مشواري الأكاديمي، عازمٌ على أن أكمل، مهما كانت الصعوبات.</p>\r\n\r\n<p>يا ترى، كم من عبدالمجيدٍ في هذا العالم؟</p>\r\n<p>كم من شغوفٍ وطموحٍ كُسرت أحلامه بحرمانٍ لا ذنب له فيه؟</p>\r\n<p>كم من ذكيٍ فضّل أن يعول أسرته على أن يُكمل دراسته؟</p>\r\n<p>كم من طالبٍ دفن أحلامه لأن أمه قالت له: \"نحن راكنين عليك، وأملنا بك كبير\"، فاختار أن يحتضن عائلته بدلًا من أن يحتضن كتبه؟</p>\r\n\r\n<p>إلى متى ستستمر هذه المعاناة؟</p>\r\n<p>إلى متى سنركض خلف أحلامٍ لا نستطيع تحقيقها؟</p>\r\n\r\n<p>صار أبسط أحلامنا أن نوفّر حياةً كريمةً لنا ولأسرنا،</p>\r\n<p>صار الحلم الذي نعيشه نحن هو حقٌ أساسيٌ في كثيرٍ من الدول،</p>\r\n<p>صرنا ننتقل من بلدٍ إلى بلدٍ بحثًا عن فرصة،</p>\r\n<p>نفكر في لقمة الغد، وصرفة الشهر القادم، والتزامات الأيام المقبلة،</p>\r\n<p>صرنا نعيش على هامش الحياة، نُداري الجراح، ونُخفي الدموع خلف ابتساماتٍ متعبة.</p>\r\n\r\n<p>لكننا، رغم كل شيء، نؤمن بالله عزّ وجل،</p>\r\n<p>هو أملنا الأكبر، وهو من يحدد مصيرنا،</p>\r\n<p>نرضى بقضائه، ونُسلّم لقدره،</p>\r\n<p>ونسأله التوفيق والسداد في الدنيا والآخرة،</p>\r\n<p>ونسأله أن يجعل لنا من ضيقنا فرجًا، ومن عسرنا يُسرًا، ومن حلمنا واقعًا يُبهج قلوبنا.</p><br>"}];

