export const welcomeSpeech: string = "🌟على درب المحاسبة: إشراقةُ علمٍ، وأمانةُ رسالةٍ، وعزيمةُ نجاح🌟\n\nأعزّاءنا طلبة قسم المحاسبة،\nنُحييكم بتحية العلم والسعي والاجتهاد، فأنتم تسيرون في طريقٍ عظيمٍ يقوم عليه بناء الاقتصاد وإدارة الثروات، وهو علمٌ رفيعٌ تتجلّى فيه الدقّة والأمانة، ويُسهم في نهضة المؤسسات والمجتمعات.\n\nلقد أنشأنا هذه البوابة لتكون منارةً تجمع المعرفة وتقرّب المعلومة، وما قمنا به هنا ما هو إلا تنظيمٌ وتجميعٌ لجهودكم المباركة التي بذلتموها في إيصال المعلومة إلى زملائكم، فالشكر الجزيل لكل من ساهم وشارك وبذل من وقته وجهده خدمةً لإخوانه الطلاب. فالفضل الأول بعد الله تعالى يعود إليكم أنتم، أصحاب الهمم العالية والنفوس المعطاءة.\n\nونعلم أن أغلبكم مشغولون بأعمالٍ أو بتربيةِ أسرٍ ومسؤولياتٍ أخرى، خصوصًا وأنكم تدرسون عن بُعد، وهذا بحد ذاته جهادٌ عظيم يدل على صبرٍ وعزيمةٍ وإصرارٍ على تحقيق النجاح. واعلموا أن العلم نورٌ، وهو أساس الحياة، ولو أنه يشقّ علينا أحيانًا بسبب انشغالنا وضيق أوقاتنا، لكن ثقوا أن ثمرته ستزهر يومًا ما، وستُسعدكم نتائج تعبكم وسهركم بإذن الله.\n\nونذكّركم أن ما تقدمونه من نفعٍ للغير هو علمٌ نافع وصدقةٌ جارية، تؤجرون عليها بإذن الله، فلا تبخلوا بعلمكم، وواصلوا عطاءكم، فبالعلم تُرفع الدرجات وتُبنى الأوطان.\n\nوفي ختام هذه الكلمة، نودّ أن نُشير إلى أن من ساهموا في مشروع هذه البوابة لهم رسائل قصيرة خاصة بكم، تحمل في طياتها نصائح وإشراقات وتجارب، لعلها تُنير طريقكم وتُلهِم خطواتكم القادمة نحو النجاح.\n\nوفقكم الله وسدّد خطاكم 🌿\nقسم المحاسبة";

export function getSubjectById(id: string): { category: Category; subject: Subject } | null {
  for (const cat of ['college','major','univ','Optional'] as Category[]) {
    const arr = platformData[cat];
    const found = arr.find(s => s.id === id);
    if (found) return { category: cat, subject: found as Subject };
  }
  return null;
}

export function getFilesByType(type: FileType): FlatFile[] {
  return allFiles.filter(f => f.type === type);
}

export function searchFiles(query: string): FlatFile[] {
  const q = query.trim().toLowerCase();
  if (!q) return [];
  return allFiles.filter(f => f.label.toLowerCase().includes(q) || f.subjectTitle.toLowerCase().includes(q));
}

export function searchSubjects(query: string): FlatSubject[] {
  const q = query.trim().toLowerCase();
  if (!q) return [];
  return allSubjects.filter(s => s.title.toLowerCase().includes(q));
}

